/* @autogenerated */
import { Component, computed, DestroyRef, effect, inject, input, output, signal, untracked } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { TranslocoModule, TranslocoService } from '@jsverse/transloco';
import { combineLatest, firstValueFrom, of } from 'rxjs';
import { downloadDataBook } from '@shared/toolkit/entity-import/excel-writer';
import { ExportColumn, ExportDefinition } from './entity-export.model';
import { cellOf, collectAll, collectSelected, Collected, EXPORT_LIMIT, formatOf, referencesOf } from './export-rows';

/** Campos que no se exportan: los asigna el sistema y la importación los ignora. */
const SYSTEM_FIELDS = ['uid', 'version'];
/** Referencias que se traducen a su nombre en cada petición. */
const NAMES_PER_REQUEST = 50;

type ExportStatus = 'choose' | 'running' | 'done' | 'cancelled' | 'failed';
type ExportScope = 'selection' | 'all';

/**
 * Exportación a Excel de los elementos de un listado, con las mismas columnas que la importación: el fichero se
 * puede editar y volver a importar. Sin selección exporta todo lo que coincide con el filtro; con selección
 * pregunta si solo lo seleccionado o todo. Recorre las páginas con una barra de progreso, hasta `limit` filas.
 */
@Component({
  selector: 'entity-export',
  standalone: true,
  imports: [MatButtonModule, MatIconModule, MatProgressBarModule, TranslocoModule],
  templateUrl: './entity-export.component.html',
  styleUrl: './entity-export.component.scss',
})
export class EntityExportComponent {
  readonly definition = input.required<ExportDefinition<any>>();
  /** Elementos seleccionados en el listado (con `uid`). */
  readonly selection = input<{ uid: string }[]>([]);
  /** Filtro actual del listado, sin paginación. */
  readonly filter = input<any>({});
  readonly closed = output<void>();

  readonly status = signal<ExportStatus>('choose');
  readonly scope = signal<ExportScope>('all');
  readonly read = signal(0);
  readonly exported = signal(0);
  readonly truncated = signal(false);
  readonly limit = computed(() => this.definition().limit ?? EXPORT_LIMIT);
  /** Total conocido de antemano (solo al exportar la selección). */
  readonly total = computed(() => (this.scope() === 'selection' ? this.selection().length : undefined));
  readonly progress = computed(() => {
    const total = this.total();
    return total ? (100 * this.read()) / total : 0;
  });

  private readonly transloco = inject(TranslocoService);
  private abort?: AbortController;

  constructor() {
    inject(DestroyRef).onDestroy(() => this.abort?.abort());
    // Sin selección no hay nada que elegir: se empieza en cuanto se abre
    effect(() => {
      if (!this.selection().length) {
        untracked(() => this.start('all'));
      }
    });
  }

  async start(scope: ExportScope): Promise<void> {
    this.abort?.abort();
    const abort = (this.abort = new AbortController());
    const definition = this.definition();
    this.scope.set(scope);
    this.status.set('running');
    this.read.set(0);
    this.truncated.set(false);
    const options = {
      pageSize: definition.pageSize,
      limit: this.limit(),
      signal: abort.signal,
      onProgress: (read: number) => this.read.set(read),
    };
    try {
      const columns = await this.columns(definition);
      const list = (filter: any) => definition.source.list(filter);
      const collected: Collected<any> =
        scope === 'selection'
          ? await collectSelected(
              list,
              this.selection().map((item) => item.uid),
              options,
            )
          : await collectAll(list, this.filter() ?? {}, options);
      abort.signal.throwIfAborted();
      const names = await this.referenceNames(definition, columns, collected.items);
      abort.signal.throwIfAborted();
      const t = (key: string, params?: Record<string, unknown>) =>
        this.transloco.translate(`common.export.${key}`, params);
      await downloadDataBook(t('fileName', { entity: definition.name, date: today() }), {
        name: t('sheet'),
        headers: columns.map((column) => column.text),
        rows: collected.items.map((item) => columns.map((column) => cellOf(item, column, names[column.field]))),
        formats: columns.map(formatOf),
      });
      this.exported.set(collected.items.length);
      this.truncated.set(collected.truncated);
      this.status.set('done');
    } catch (error) {
      if (abort === this.abort) {
        this.status.set(abort.signal.aborted ? 'cancelled' : 'failed');
      }
    }
  }

  cancel(): void {
    this.abort?.abort();
  }

  /** Vuelve al principio: a elegir qué exportar o, sin selección, a exportar otra vez. */
  restart(): void {
    if (this.selection().length) {
      this.status.set('choose');
    } else {
      this.start('all');
    }
  }

  /** Columnas de la importación que se pueden leer: sin las sensibles ni las que oculta el ACL. */
  private async columns(definition: ExportDefinition<any>): Promise<ExportColumn[]> {
    const acl = await firstValueFrom(definition.source.acl());
    const hidden = acl?.fields?.noVisibles ?? [];
    const columns = definition.columns.filter(
      (column) =>
        !SYSTEM_FIELDS.includes(column.field) &&
        !definition.sensitive?.includes(column.field) &&
        !hidden.includes(column.field),
    );
    const keys = columns.flatMap((column) => [column.label, ...(column.options ?? []).map((option) => option.label)]);
    const texts: Record<string, string> = keys.length
      ? await firstValueFrom(
          combineLatest(
            Object.fromEntries(keys.map((key) => [key, this.transloco.selectTranslate(key, {}, definition.scope)])),
          ),
        )
      : {};
    return columns.map((column) => ({
      ...column,
      text: texts[column.label] ?? column.field,
      optionTexts: column.options
        ? Object.fromEntries(column.options.map((option) => [option.value, texts[option.label] ?? option.value]))
        : undefined,
    }));
  }

  /** Nombre de cada referencia, por campo, pedido por bloques. */
  private async referenceNames(
    definition: ExportDefinition<any>,
    columns: ExportColumn[],
    items: any[],
  ): Promise<Record<string, Record<string, string>>> {
    const result: Record<string, Record<string, string>> = {};
    for (const column of columns) {
      const reference = definition.references?.[column.field];
      if (column.type !== 'reference' || !reference) {
        continue;
      }
      const refs = referencesOf(items, column.field);
      result[column.field] = {};
      for (let start = 0; start < refs.length; start += NAMES_PER_REQUEST) {
        const names = await firstValueFrom(reference.names(refs.slice(start, start + NAMES_PER_REQUEST)) ?? of({}));
        Object.assign(result[column.field], names);
      }
    }
    return result;
  }
}

/** Fecha local `aaaa-mm-dd` para el nombre del fichero. */
function today(): string {
  const now = new Date();
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}
